/**
 * COMBINED_LLM=1 embedding-input ablation — custom-150.
 *
 * Tests hypothesis: does prepending context to chunk.text for embeddings hurt
 * exact-token / source-navigation recall?
 *
 * Two temp collections indexed with qwen2.5:3b-instruct + COMBINED_LLM=1:
 *   A. context+text  — production default (context\n\ntext)
 *   B. text-only     — EMBED_INPUT=text; payload context/tags still generated by LLM
 *
 * Both queried with all custom-150 queries. Report written to results/.
 *
 * Usage:
 *   CONTEXT_MODEL=qwen2.5:3b-instruct COMBINED_LLM=1 node benchmarks/retrieval/custom-150/combined-embed-input-ablation.js
 *   (or via npm run bench:custom150:embed-ablation after adding to package.json)
 *
 * Production code change: EMBED_INPUT=text flag added to src/indexer/index.js line 118.
 * Default behavior (context+text) is unchanged when EMBED_INPUT is unset.
 *
 * All transient files live under .tmp/ (gitignored).
 * Stable collection bench-retrieval-custom-150 is never touched.
 */

import 'dotenv/config';
import { spawnSync }                                    from 'child_process';
import { existsSync, mkdirSync, readdirSync, copyFileSync, rmSync, writeFileSync, readFileSync } from 'fs';
import { resolve, join, dirname }                       from 'path';
import { fileURLToPath }                                from 'url';

import { listCollections, createCollection, deleteCollection, hybridSearch } from '../../../src/core/qdrant.js';
import { embedForSearch, SCHEMA_VERSION }               from '../../../src/core/embeddings.js';
import { loadConfig, saveConfig, resolveEnvProviders }  from '../../../src/core/config.js';

const ROOT           = resolve(dirname(fileURLToPath(import.meta.url)), '../../../');
const FIXTURES_SHARED = join(ROOT, 'benchmarks', 'retrieval', 'fixtures', 'docs');
const FIXTURES_C50    = join(ROOT, 'benchmarks', 'retrieval', 'custom-50', 'fixtures', 'docs');
const FIXTURES_OWN    = join(ROOT, 'benchmarks', 'retrieval', 'custom-150', 'fixtures', 'docs');
const QUERIES_PATH    = join(ROOT, 'benchmarks', 'retrieval', 'custom-150', 'queries.json');
const RESULTS_DIR     = join(ROOT, 'benchmarks', 'retrieval', 'results');

const CONTEXT_MODEL = process.env.CONTEXT_MODEL || 'qwen2.5:3b-instruct';
const QDRANT_URL    = (process.env.QDRANT_URL ?? '').replace(/\/$/, '');
const TOP_K         = 10;
const BENCH_WINDOW  = 1;
const KEEP          = process.env.KEEP_COLLECTIONS === '1';

const STAMP           = Date.now();
const COL_CTX_TEXT    = `bench-ablation-ctx-text-${STAMP}`;
const COL_TEXT_ONLY   = `bench-ablation-text-only-${STAMP}`;
const CORPUS_DIR      = join(ROOT, '.tmp', `ablation-corpus-${STAMP}`);
const CHUNKS_CTX      = join(ROOT, '.tmp', `ablation-chunks-ctx-${STAMP}`);
const CHUNKS_TEXT     = join(ROOT, '.tmp', `ablation-chunks-text-${STAMP}`);

// ── Fixture list (mirrors custom-150/run.js) ──────────────────────────────────

function buildFixtureList() {
  const list = [
    { name: 'providers.md',         dir: FIXTURES_SHARED },
    { name: 'qdrant.md',            dir: FIXTURES_SHARED },
    { name: 'chunking.md',          dir: FIXTURES_SHARED },
    { name: 'sync.md',              dir: FIXTURES_SHARED },
    { name: 'mcp-workflow.md',      dir: FIXTURES_C50 },
    { name: 'obsidian.md',          dir: FIXTURES_C50 },
    { name: 'project-structure.md', dir: FIXTURES_C50 },
    { name: 'benchmarking.md',      dir: FIXTURES_C50 },
    { name: 'config-env.md',        dir: FIXTURES_C50 },
    { name: 'multilingual.md',      dir: FIXTURES_C50 },
  ];
  if (existsSync(FIXTURES_OWN)) {
    for (const name of readdirSync(FIXTURES_OWN).filter(f => f.endsWith('.md'))) {
      list.push({ name, dir: FIXTURES_OWN });
    }
  }
  return list;
}

function buildCorpus() {
  rmSync(CORPUS_DIR, { recursive: true, force: true });
  mkdirSync(CORPUS_DIR, { recursive: true });
  for (const { name, dir } of buildFixtureList()) {
    const src = join(dir, name);
    if (!existsSync(src)) throw new Error(`fixture missing: ${src}`);
    copyFileSync(src, join(CORPUS_DIR, name));
  }
  console.log(`  corpus built: ${buildFixtureList().length} files → ${CORPUS_DIR}`);
}

// ── Qdrant collection helpers ─────────────────────────────────────────────────

async function ensureAblationCollection(name) {
  const cols = await listCollections();
  if (!cols.includes(name)) await createCollection(name, 1024);
  const { denseProvider, denseModel, sparseProvider } = resolveEnvProviders();
  const cfg = loadConfig();
  cfg.collections ??= {};
  cfg.collections[name] = {
    denseProvider, denseModel, sparseProvider,
    embeddingSchemaVersion: SCHEMA_VERSION,
    vectorSize: 1024,
    description: `embed-input ablation bench — auto-managed (${STAMP})`,
  };
  saveConfig(cfg);
}

async function deleteBenchCollection(name) {
  try {
    await deleteCollection(name);
    console.log(`  [cleanup] deleted "${name}"`);
  } catch {
    console.log(`  [cleanup] could not delete "${name}"`);
  }
}

function cleanupTransient() {
  try { rmSync(CORPUS_DIR,  { recursive: true, force: true }); } catch { /* ignore */ }
  try { rmSync(CHUNKS_CTX,  { recursive: true, force: true }); } catch { /* ignore */ }
  try { rmSync(CHUNKS_TEXT, { recursive: true, force: true }); } catch { /* ignore */ }
}

function cleanupConfigEntries() {
  try {
    const cfg = loadConfig();
    if (!cfg.collections) return;
    delete cfg.collections[COL_CTX_TEXT];
    delete cfg.collections[COL_TEXT_ONLY];
    saveConfig(cfg);
  } catch { /* best-effort */ }
}

// ── Indexer runner ────────────────────────────────────────────────────────────

function parseProfilerOutput(stdout) {
  const phaseMs = {};
  const re = /^\s+(\S+)\s+(\d+)\s+ms/;
  for (const line of stdout.split('\n')) {
    const m = line.match(re);
    if (!m) continue;
    const [, phase, ms] = m;
    if (!phaseMs[phase]) phaseMs[phase] = [];
    phaseMs[phase].push(parseInt(ms, 10));
  }
  const result = {};
  for (const [phase, vals] of Object.entries(phaseMs)) {
    result[phase] = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
  }
  return result;
}

function runIndexer(collection, extraEnv, chunksOutDir, label) {
  console.log(`\n[ablation] Indexing ${label}...`);
  mkdirSync(chunksOutDir, { recursive: true });
  const env = {
    ...process.env,
    COLLECTION:     collection,
    SOURCE_ROOT:    CORPUS_DIR,
    ONNX_EMBED:     '1',
    COMBINED_LLM:   '1',
    CONTEXT_MODEL:  CONTEXT_MODEL,
    CHUNKS_OUT_DIR: chunksOutDir,
    INDEX_PROFILE:  '1',
    ...extraEnv,
  };
  const t0 = Date.now();
  const result = spawnSync('node', ['src/indexer/index.js', CORPUS_DIR], {
    cwd: ROOT,
    env,
    encoding: 'utf8',
    maxBuffer: 30 * 1024 * 1024,
  });
  const totalMs = Date.now() - t0;
  const stdout = result.stdout ?? '';
  const stderr = result.stderr ?? '';

  if (result.status !== 0) {
    console.error(`  FAILED (exit ${result.status})`);
    console.error(stderr.slice(-3000));
    return { ok: false, totalMs, phases: {}, fallbacks: 0, indexed: 0, stdout, stderr };
  }

  const phases    = parseProfilerOutput(stdout);
  const fallbacks = (stderr.match(/\[combined\] parse failed/g) ?? []).length;
  const indexed   = parseInt((stdout.match(/(\d+) indexed/) ?? [])[1] ?? '0', 10);
  console.log(`  done in ${totalMs} ms — exit 0, ${indexed} file(s), ${fallbacks} fallbacks`);
  return { ok: true, totalMs, phases, fallbacks, indexed, stdout, stderr };
}

// ── Scroll helpers (with first-page retry for stale keep-alive) ───────────────

async function scrollPage(collection, offset) {
  const body = { limit: 100, with_payload: true, with_vectors: false };
  if (offset !== null) body.offset = offset;
  const r = await fetch(`${QDRANT_URL}/collections/${collection}/points/scroll`, {
    method: 'POST',
    headers: { 'api-key': process.env.QDRANT_KEY ?? '', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(60000),
  });
  if (!r.ok) {
    const text = await r.text().catch(() => '');
    throw new Error(`Qdrant scroll "${collection}" returned ${r.status}: ${text.slice(0, 200)}`);
  }
  return r.json();
}

async function scrollAll(collection) {
  const points = [];
  let offset   = null;
  while (true) {
    let data;
    try {
      data = await scrollPage(collection, offset);
    } catch (e) {
      if (offset === null && e.message === 'fetch failed') {
        console.log('  [scroll] network error on first page — retrying once...');
        await new Promise(r => setTimeout(r, 2000));
        data = await scrollPage(collection, offset);
      } else {
        throw e;
      }
    }
    const batch = data?.result?.points ?? [];
    points.push(...batch);
    offset = data?.result?.next_page_offset ?? null;
    if (offset === null || batch.length === 0) break;
  }
  return points;
}

// ── Query helpers ─────────────────────────────────────────────────────────────

function tokenise(str) {
  return (str ?? '').toLowerCase().match(/[\p{L}\p{N}_]+/gu) ?? [];
}

function buildQrels(relevantChunks) {
  const map = new Map();
  for (const rc of (relevantChunks ?? [])) map.set(rc.chunkId, rc.relevance ?? 3);
  return map;
}

function normaliseQuery(q) {
  return {
    id:                    q.id,
    type:                  q.type ?? 'file-level',
    query:                 q.query,
    relevantChunks:        q.relevantChunks ?? [],
    qrels:                 buildQrels(q.relevantChunks),
    expectedTokens:        q.expectedTokens ? q.expectedTokens.flatMap(t => tokenise(t)).filter(Boolean) : null,
    shouldHaveNoStrongHit: q.shouldHaveNoStrongHit ?? false,
    note:                  q.note ?? '',
  };
}

// ── Metric helpers ────────────────────────────────────────────────────────────

function resultChunkId(r) {
  const sf = r.payload?.source_file;
  const ci = r.payload?.chunk_index;
  if (!sf || ci == null) return null;
  return `${sf}#${ci}`;
}

function idealDCG(qrels, k) {
  const gains = [...qrels.values()].map(rel => Math.pow(2, rel) - 1).sort((a, b) => b - a);
  let idcg = 0;
  for (let i = 0; i < Math.min(gains.length, k); i++) idcg += gains[i] / Math.log2(i + 2);
  return idcg;
}

function gradedNDCG(results, qrels, k) {
  if (!qrels.size) return null;
  const topK = results.slice(0, k);
  let dcg = 0;
  for (let i = 0; i < topK.length; i++) {
    const rel = qrels.get(resultChunkId(topK[i])) ?? 0;
    dcg += (Math.pow(2, rel) - 1) / Math.log2(i + 2);
  }
  const idcg = idealDCG(qrels, k);
  return idcg === 0 ? 0 : dcg / idcg;
}

function chunkRecallHit(results, qrels, k, minRel = 3) {
  if (!qrels.size) return null;
  const relevant = new Set([...qrels.entries()].filter(([, r]) => r >= minRel).map(([id]) => id));
  if (!relevant.size) return null;
  return results.slice(0, k).some(r => relevant.has(resultChunkId(r)));
}

function mrrAt(results, qrels, k, minRel = 3) {
  if (!qrels.size) return null;
  const relevant = new Set([...qrels.entries()].filter(([, r]) => r >= minRel).map(([id]) => id));
  if (!relevant.size) return null;
  for (let i = 0; i < Math.min(results.length, k); i++) {
    if (relevant.has(resultChunkId(results[i]))) return 1 / (i + 1);
  }
  return 0;
}

function parseChunkId(cid) {
  if (!cid) return null;
  const h = cid.lastIndexOf('#');
  if (h < 0) return null;
  const src = cid.slice(0, h);
  const idx = parseInt(cid.slice(h + 1), 10);
  return src && Number.isFinite(idx) ? { src, idx } : null;
}

function windowRecallHit(results, qrels, k, window) {
  if (!qrels.size) return null;
  const exactIds = [...qrels.entries()].filter(([, r]) => r >= 3).map(([id]) => id);
  if (!exactIds.length) return null;
  const topK = results.slice(0, k);
  if (topK.some(r => { const cid = resultChunkId(r); return cid && qrels.get(cid) >= 3; })) return true;
  for (const exactId of exactIds) {
    const ep = parseChunkId(exactId);
    if (!ep) continue;
    if (topK.some(r => {
      const rp = parseChunkId(resultChunkId(r));
      return rp && rp.src === ep.src && Math.abs(rp.idx - ep.idx) <= window;
    })) return true;
  }
  return false;
}

function negPass(results, query) {
  if (!results.length) return true;
  const top1Words = new Set([
    ...tokenise(results[0].payload?.text    ?? ''),
    ...tokenise(results[0].payload?.section ?? ''),
  ]);
  return !(query.expectedTokens ?? []).some(t => top1Words.has(t));
}

function computeMetrics(queryResults) {
  const positives = queryResults.filter(r => !r.query.shouldHaveNoStrongHit);
  const negatives = queryResults.filter(r =>  r.query.shouldHaveNoStrongHit);
  const hasExact    = positives.filter(r => [...r.query.qrels.values()].some(v => v >= 3)).length;
  const hasAnyQrels = positives.filter(r => r.query.qrels.size > 0).length;

  let cr3 = 0, cr5 = 0, cr10 = 0, wr5 = 0, wr10 = 0, supp = 0, ndcgSum = 0, mrrSum = 0, mrrCount = 0, negOk = 0;
  for (const r of positives) {
    if (chunkRecallHit(r.results, r.query.qrels, 3,      3)) cr3++;
    if (chunkRecallHit(r.results, r.query.qrels, 5,      3)) cr5++;
    if (chunkRecallHit(r.results, r.query.qrels, TOP_K,  3)) cr10++;
    if (windowRecallHit(r.results, r.query.qrels, 5,      BENCH_WINDOW)) wr5++;
    if (windowRecallHit(r.results, r.query.qrels, TOP_K,  BENCH_WINDOW)) wr10++;
    if (chunkRecallHit(r.results, r.query.qrels, TOP_K,  2)) supp++;
    const nd = gradedNDCG(r.results, r.query.qrels, TOP_K);
    const mv = mrrAt(r.results, r.query.qrels, 10, 3);
    if (nd !== null) ndcgSum += nd;
    if (mv !== null) { mrrSum += mv; mrrCount++; }
  }
  for (const r of negatives) { if (negPass(r.results, r.query)) negOk++; }

  return {
    chunkRecall3:    hasExact > 0    ? cr3 / hasExact     : null,
    chunkRecall5:    hasExact > 0    ? cr5 / hasExact     : null,
    chunkRecall10:   hasExact > 0    ? cr10 / hasExact    : null,
    windowRecall5:   hasExact > 0    ? wr5 / hasExact     : null,
    windowRecall10:  hasExact > 0    ? wr10 / hasExact    : null,
    supportRecall:   hasAnyQrels > 0 ? supp / hasAnyQrels : null,
    ndcg10:          hasAnyQrels > 0 ? ndcgSum / hasAnyQrels : null,
    mrr10:           mrrCount > 0    ? mrrSum / mrrCount  : null,
    negPassRate:     negatives.length > 0 ? negOk / negatives.length : null,
    nPositive: positives.length, nNegative: negatives.length,
  };
}

function computeByType(queryResults) {
  const types = [...new Set(queryResults.map(r => r.query.type))];
  const out = {};
  for (const t of types) {
    const subset = queryResults.filter(r => r.query.type === t);
    out[t] = computeMetrics(subset);
  }
  return out;
}

// ── Search ────────────────────────────────────────────────────────────────────

async function runAllQueries(collection, queries) {
  const qr = [];
  for (const q of queries) {
    process.stdout.write(`  ${q.id}: ${q.query.slice(0, 42)}... `);
    const t0 = Date.now();
    const { dense, sparse } = await embedForSearch(collection, q.query);
    const results = await hybridSearch(collection, dense, sparse, TOP_K);
    const latency = Date.now() - t0;
    qr.push({ query: q, results, latency });
    const hit = q.shouldHaveNoStrongHit
      ? (negPass(results, q) ? '✓neg' : '✗neg')
      : (chunkRecallHit(results, q.qrels, 5, 3) ? '✓' : '✗');
    console.log(`${hit} (${latency}ms)`);
  }
  return qr;
}

// ── Report ────────────────────────────────────────────────────────────────────

function pct(v)  { return v == null ? 'n/a' : `${(v * 100).toFixed(1)}%`; }
function f3(v)   { return v == null ? 'n/a' : v.toFixed(3); }
function d(a, b) { if (a == null || b == null) return '—'; const v = a - b; return Math.abs(v) < 0.0005 ? '—' : (v > 0 ? '+' : '') + v.toFixed(3); }
function dpct(a, b) { if (a == null || b == null) return '—'; const v = (a - b) * 100; return Math.abs(v) < 0.05 ? '—' : (v > 0 ? '+' : '') + v.toFixed(1) + ' pp'; }

function buildReport(opts) {
  const { idxCtx, idxText, mCtx, mText, byTypeCtx, byTypeText,
          ptCtx, ptText, ctxResults, textResults, queries } = opts;

  const now = new Date();
  const stamp = [
    now.getFullYear(),
    String(now.getMonth()+1).padStart(2,'0'),
    String(now.getDate()).padStart(2,'0'),
    'T',
    String(now.getHours()).padStart(2,'0'),
    String(now.getMinutes()).padStart(2,'0'),
  ].join('');

  const historical = {
    chunkRecall5:  0.681,
    chunkRecall10: 0.764,
    mrr10:         0.517,
    ndcg10:        0.566,
  };

  const lines = [];
  const L = (...s) => lines.push(...s);

  L(
    `# COMBINED_LLM=1 Embedding-Input Ablation — custom-150 — ${stamp}`,
    ``,
    `## Hypothesis`,
    ``,
    `Prepending LLM-generated context to \`chunk.text\` for embeddings may blur exact-token and`,
    `source-navigation ranking. Ablation: keep qwen2.5 combined context/tags as payload, but embed`,
    `only \`chunk.text\` (no context prefix). If chunkRecall@5 improves without hurting MRR/nDCG,`,
    `embedding input should become configurable.`,
    ``,
    `## Environment`,
    ``,
    `| Item | Value |`,
    `|------|-------|`,
    `| CONTEXT_MODEL | ${CONTEXT_MODEL} |`,
    `| COMBINED_LLM | 1 |`,
    `| ONNX_EMBED | 1 |`,
    `| BENCH_EMBED_INPUT (context+text) | unset (default) |`,
    `| BENCH_EMBED_INPUT (text-only) | text |`,
    `| Corpus | custom-150 fixture docs (${buildFixtureList().length} files) |`,
    `| Queries | ${queries.length} (v3 schema) |`,
    `| Top-K | ${TOP_K} |`,
    `| Window | ${BENCH_WINDOW} |`,
    ``,
    `## Temp Collections`,
    ``,
    `| Arm | Collection | Points | Wall time | Fallbacks |`,
    `|-----|-----------|--------|-----------|-----------|`,
    `| context+text | \`${COL_CTX_TEXT}\` | ${ptCtx} | ${idxCtx.totalMs} ms | ${idxCtx.fallbacks} |`,
    `| text-only | \`${COL_TEXT_ONLY}\` | ${ptText} | ${idxText.totalMs} ms | ${idxText.fallbacks} |`,
    ``,
    `## Aggregate Metrics`,
    ``,
    `| Metric | context+text | text-only | Δ (text−ctx) | Historical ONNX ref |`,
    `|--------|-------------|-----------|--------------|---------------------|`,
    `| chunkRecall@3 | ${pct(mCtx.chunkRecall3)} | ${pct(mText.chunkRecall3)} | ${dpct(mText.chunkRecall3, mCtx.chunkRecall3)} | — |`,
    `| chunkRecall@5 | ${pct(mCtx.chunkRecall5)} | ${pct(mText.chunkRecall5)} | ${dpct(mText.chunkRecall5, mCtx.chunkRecall5)} | ~${pct(historical.chunkRecall5)} |`,
    `| chunkRecall@10 | ${pct(mCtx.chunkRecall10)} | ${pct(mText.chunkRecall10)} | ${dpct(mText.chunkRecall10, mCtx.chunkRecall10)} | ~${pct(historical.chunkRecall10)} |`,
    `| windowRecall@5 | ${pct(mCtx.windowRecall5)} | ${pct(mText.windowRecall5)} | ${dpct(mText.windowRecall5, mCtx.windowRecall5)} | — |`,
    `| windowRecall@10 | ${pct(mCtx.windowRecall10)} | ${pct(mText.windowRecall10)} | ${dpct(mText.windowRecall10, mCtx.windowRecall10)} | — |`,
    `| supportRecall@10 | ${pct(mCtx.supportRecall)} | ${pct(mText.supportRecall)} | ${dpct(mText.supportRecall, mCtx.supportRecall)} | — |`,
    `| nDCG@10 | ${f3(mCtx.ndcg10)} | ${f3(mText.ndcg10)} | ${d(mText.ndcg10, mCtx.ndcg10)} | ~${f3(historical.ndcg10)} |`,
    `| MRR@10 | ${f3(mCtx.mrr10)} | ${f3(mText.mrr10)} | ${d(mText.mrr10, mCtx.mrr10)} | ~${f3(historical.mrr10)} |`,
    `| negativePass | ${pct(mCtx.negPassRate)} | ${pct(mText.negPassRate)} | — | — |`,
    ``,
    `## Per-Type Breakdown`,
    ``,
    `| Type | ctx+text cr@5 | text-only cr@5 | Δcr@5 | ctx+text MRR | text-only MRR | ΔMRR |`,
    `|------|--------------|---------------|-------|-------------|--------------|------|`,
  );

  const allTypes = [...new Set([...Object.keys(byTypeCtx), ...Object.keys(byTypeText)])].sort();
  for (const t of allTypes) {
    const mc = byTypeCtx[t];
    const mt = byTypeText[t];
    L(`| ${t} | ${pct(mc?.chunkRecall5)} | ${pct(mt?.chunkRecall5)} | ${dpct(mt?.chunkRecall5, mc?.chunkRecall5)} | ${f3(mc?.mrr10)} | ${f3(mt?.mrr10)} | ${d(mt?.mrr10, mc?.mrr10)} |`);
  }

  // Per-query diff: text-only vs context+text
  L(``, `## Per-Query Diff (text-only vs context+text, positive queries)`);

  const positiveQueries = queries.filter(q => !q.shouldHaveNoStrongHit && q.qrels.size > 0);
  const diffRows = [];
  for (const q of positiveQueries) {
    const cr = ctxResults.find(r => r.query.id === q.id);
    const tr = textResults.find(r => r.query.id === q.id);
    if (!cr || !tr) continue;
    const cMrr  = mrrAt(cr.results, q.qrels, 10, 3) ?? 0;
    const tMrr  = mrrAt(tr.results, q.qrels, 10, 3) ?? 0;
    const cCr5  = chunkRecallHit(cr.results, q.qrels, 5, 3) ? 1 : 0;
    const tCr5  = chunkRecallHit(tr.results, q.qrels, 5, 3) ? 1 : 0;
    const mrrDelta = tMrr - cMrr;
    let change = '—';
    if      (cCr5 === 0 && tCr5 === 1) change = '**recall gained**';
    else if (cCr5 === 1 && tCr5 === 0) change = '**recall lost**';
    else if (mrrDelta >  0.001) change = 'improved';
    else if (mrrDelta < -0.001) change = 'regressed';
    diffRows.push({ id: q.id, type: q.type, cMrr, tMrr, mrrDelta, cCr5, tCr5, change });
  }

  const changed = diffRows.filter(r => r.change !== '—');
  L(``, `${changed.length} queries changed (${diffRows.filter(r=>r.change==='**recall gained**').length} recall gained, ${diffRows.filter(r=>r.change==='**recall lost**').length} recall lost).`, ``);
  L(`| ID | type | ctx MRR | text MRR | ΔMRR | ctx cr@5 | text cr@5 | change |`);
  L(`|----|------|---------|----------|------|----------|-----------|--------|`);
  for (const r of diffRows.filter(r => r.change !== '—')) {
    L(`| ${r.id} | ${r.type} | ${f3(r.cMrr)} | ${f3(r.tMrr)} | ${d(r.tMrr, r.cMrr)} | ${r.cCr5 ? '✓' : '✗'} | ${r.tCr5 ? '✓' : '✗'} | ${r.change} |`);
  }

  // Missed by both
  const missedBoth = positiveQueries.filter(q => {
    const cr = ctxResults.find(r => r.query.id === q.id);
    const tr = textResults.find(r => r.query.id === q.id);
    return cr && tr &&
      !chunkRecallHit(cr.results, q.qrels, 5, 3) &&
      !chunkRecallHit(tr.results, q.qrels, 5, 3);
  });
  if (missedBoth.length) {
    L(``, `### Missed by both arms (chunkRecall@5)`);
    L(``, `| ID | type | note |`);
    L(`|----|------|------|`);
    for (const q of missedBoth) {
      L(`| ${q.id} | ${q.type} | ${q.note || '—'} |`);
    }
  }

  // Verdict
  const cr5Gain = (mText.chunkRecall5 ?? 0) - (mCtx.chunkRecall5 ?? 0);
  const mrrLoss = (mCtx.mrr10 ?? 0) - (mText.mrr10 ?? 0);
  const ndcgLoss = (mCtx.ndcg10 ?? 0) - (mText.ndcg10 ?? 0);

  let verdict, reason;
  if (cr5Gain > 0.02 && mrrLoss < 0.02 && ndcgLoss < 0.02) {
    verdict = 'PROCEED';
    reason = `text-only improves chunkRecall@5 by ${(cr5Gain*100).toFixed(1)} pp without material MRR/nDCG loss — context prefix in embedding input is net-negative for recall. Consider making EMBED_INPUT configurable or changing default.`;
  } else if (cr5Gain > 0.005 && mrrLoss < 0.01) {
    verdict = 'PROCEED (marginal)';
    reason = `text-only shows a small chunkRecall@5 gain (+${(cr5Gain*100).toFixed(1)} pp) with negligible MRR impact — worth confirming on a second run before changing defaults.`;
  } else if (cr5Gain <= 0 && mrrLoss < 0.01) {
    verdict = 'DEFER';
    reason = `text-only does not improve chunkRecall@5 (Δ=${(cr5Gain*100).toFixed(1)} pp). Hypothesis not confirmed — context prefix in embedding input is not the primary recall bottleneck.`;
  } else if (mrrLoss >= 0.02 || ndcgLoss >= 0.02) {
    verdict = 'DEFER';
    reason = `text-only causes material MRR or nDCG regression (ΔMRR=${d(mText.mrr10, mCtx.mrr10)}, ΔnDCG=${d(mText.ndcg10, mCtx.ndcg10)}). Recall gain does not justify the ranking loss.`;
  } else {
    verdict = 'DEFER';
    reason = `Mixed results — no clear winner. Investigate per-type breakdown before deciding.`;
  }

  L(
    ``,
    `## Verdict`,
    ``,
    `**${verdict}**`,
    ``,
    reason,
    ``,
    `| Signal | Value |`,
    `|--------|-------|`,
    `| chunkRecall@5 Δ (text−ctx) | ${dpct(mText.chunkRecall5, mCtx.chunkRecall5)} |`,
    `| MRR@10 Δ (text−ctx) | ${d(mText.mrr10, mCtx.mrr10)} |`,
    `| nDCG@10 Δ (text−ctx) | ${d(mText.ndcg10, mCtx.ndcg10)} |`,
    `| chunkRecall@10 Δ | ${dpct(mText.chunkRecall10, mCtx.chunkRecall10)} |`,
    `| Recall gained (queries) | ${diffRows.filter(r=>r.change==='**recall gained**').length} |`,
    `| Recall lost (queries) | ${diffRows.filter(r=>r.change==='**recall lost**').length} |`,
    ``,
    `---`,
    ``,
    `*Generated: ${stamp} — stamp ${STAMP}*`,
  );

  return { lines, stamp };
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  console.log(`[ablation] COMBINED_LLM=1 embed-input ablation — custom-150`);
  console.log(`  CONTEXT_MODEL: ${CONTEXT_MODEL}`);
  console.log(`  collections:   ${COL_CTX_TEXT}  |  ${COL_TEXT_ONLY}`);

  buildCorpus();

  await ensureAblationCollection(COL_CTX_TEXT);
  await ensureAblationCollection(COL_TEXT_ONLY);

  const idxCtx  = runIndexer(COL_CTX_TEXT,  {},                         CHUNKS_CTX,  'A: context+text (default)');
  const idxText = runIndexer(COL_TEXT_ONLY, { BENCH_EMBED_INPUT: 'text' }, CHUNKS_TEXT, 'B: text-only (ablation)');

  if (!idxCtx.ok || !idxText.ok) {
    throw new Error('Indexer run(s) failed — cannot continue. Check stderr above.');
  }

  console.log('\n[ablation] Fetching point counts...');
  const [allCtx, allText] = await Promise.all([scrollAll(COL_CTX_TEXT), scrollAll(COL_TEXT_ONLY)]);
  const ptCtx  = allCtx.length;
  const ptText = allText.length;
  console.log(`  context+text: ${ptCtx} points`);
  console.log(`  text-only:    ${ptText} points`);

  const rawQueries = JSON.parse(readFileSync(QUERIES_PATH, 'utf8'));
  const queries = (rawQueries.queries ?? rawQueries).map(normaliseQuery);
  console.log(`\n[ablation] Loaded ${queries.length} queries`);

  console.log('\n[ablation] Querying context+text collection...');
  const ctxResults  = await runAllQueries(COL_CTX_TEXT,  queries);
  console.log('\n[ablation] Querying text-only collection...');
  const textResults = await runAllQueries(COL_TEXT_ONLY, queries);

  const mCtx       = computeMetrics(ctxResults);
  const mText      = computeMetrics(textResults);
  const byTypeCtx  = computeByType(ctxResults);
  const byTypeText = computeByType(textResults);

  const { lines, stamp } = buildReport({
    idxCtx, idxText, mCtx, mText, byTypeCtx, byTypeText,
    ptCtx, ptText, ctxResults, textResults, queries,
  });

  const reportFile = join(RESULTS_DIR, `${stamp}-qwen25-custom150-embed-input-ablation.md`);
  writeFileSync(reportFile, lines.join('\n') + '\n');
  console.log(`\n[ablation] Report: ${reportFile}`);

  console.log('\n[ablation] Summary');
  console.log(`  context+text  cr@5=${pct(mCtx.chunkRecall5)}  cr@10=${pct(mCtx.chunkRecall10)}  MRR=${f3(mCtx.mrr10)}  nDCG=${f3(mCtx.ndcg10)}`);
  console.log(`  text-only     cr@5=${pct(mText.chunkRecall5)}  cr@10=${pct(mText.chunkRecall10)}  MRR=${f3(mText.mrr10)}  nDCG=${f3(mText.ndcg10)}`);

  if (!KEEP) {
    console.log('\n[ablation] Cleaning up...');
    await deleteBenchCollection(COL_CTX_TEXT);
    await deleteBenchCollection(COL_TEXT_ONLY);
    cleanupConfigEntries();
    cleanupTransient();
  }
}

main().catch(err => {
  console.error('[ablation] fatal:', err.message);
  if (err.cause) console.error('[ablation] cause:', err.cause?.message ?? err.cause);
  console.error('[ablation] stack:', err.stack?.split('\n').slice(1, 4).join(' | '));
  process.exit(1);
});

